#include <stdio.h>

#define MAXN 1000

/* opp[i][t] = valor da face oposta (base) quando o topo da die i vale t
   lat[i][t] = melhor contribuição lateral da die i com topo t
               (máximo das 4 faces laterais restantes)            */
static int opp[MAXN][7];
static int lat[MAXN][7];

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    for (int i = 0; i < n; i++) {
        int a, b, c, d, e, f;
        if (scanf("%d %d %d %d %d %d", &a, &b, &c, &d, &e, &f) != 6) return 0;

        /* faces opostas: A-F, B-D, C-E */
        int o[7] = {0, 0, 0, 0, 0, 0, 0};
        o[a] = f; o[f] = a;
        o[b] = d; o[d] = b;
        o[c] = e; o[e] = c;

        for (int t = 1; t <= 6; t++) {
            int m = 0;
            for (int u = 1; u <= 6; u++)
                if (u != t && u != o[t] && u > m) m = u;
            opp[i][t] = o[t];
            lat[i][t] = m;
        }
    }

    /* dp[t] = melhor soma do lado considerando os dados processados,
       com o dado atual tendo topo t.
       Como cada die gira horizontalmente de forma independente,
       o melhor lado recebe max(face lateral) de cada die.          */
    long long dp[7], ndp[7];
    for (int t = 1; t <= 6; t++) dp[t] = lat[0][t];

    for (int i = 1; i < n; i++) {
        /* base da die i (opp[i][t]) deve valer o topo da die i-1 */
        for (int t = 1; t <= 6; t++)
            ndp[t] = (long long)lat[i][t] + dp[opp[i][t]];
        for (int t = 1; t <= 6; t++) dp[t] = ndp[t];
    }

    long long ans = dp[1];
    for (int t = 2; t <= 6; t++)
        if (dp[t] > ans) ans = dp[t];

    printf("%lld\n", ans);
    return 0;
}
